import {ToolRegistry} from './registry.js';
import {setLogger} from '../../shared/logger.js';

function registryWith(properties: Record<string, Record<string, unknown>>, required: string[]) {
  const registry = new ToolRegistry();
  const calls: Array<Record<string, unknown>> = [];
  registry.register(
    {name: 'probe', description: 'Probe tool', inputSchema: {type: 'object', properties, required}},
    async input => {
      calls.push(input);
      return 'ok';
    }
  );
  return {registry, calls};
}

describe('ToolRegistry.execute', () => {
  afterEach(() => {
    setLogger(undefined);
  });

  it('returns a rejection naming location as required and never calls the executor for {}', async () => {
    const {registry, calls} = registryWith({location: {type: 'string'}}, ['location']);

    const {result} = await registry.execute('probe', {});

    expect({executorCalls: calls.length, result}).toEqual({
      executorCalls: 0,
      result: expect.stringMatching(/location.*required|required.*location/),
    });
  });

  it('rejects a number where a string is required naming the path and type but never the value', async () => {
    const logLines: string[] = [];
    const record = (...args: unknown[]) => {
      logLines.push(JSON.stringify(args));
    };
    setLogger({debug: record, info: record, warn: record, error: record});
    const {registry, calls} = registryWith({email: {type: 'string'}}, ['email']);

    const {result} = await registry.execute('probe', {email: 4155550123});

    expect({
      executorCalls: calls.length,
      result,
      leaks: [result, ...logLines].some(text => text.includes('4155550123')),
    }).toEqual({
      executorCalls: 0,
      result: expect.stringMatching(/email.*string/),
      leaks: false,
    });
  });
});

describe('ToolRegistry.register', () => {
  it('throws naming the tool when a static inputSchema cannot be compiled', () => {
    const registry = new ToolRegistry();

    const register = () =>
      registry.register(
        {
          name: 'broken_probe',
          description: 'Probe tool',
          inputSchema: {type: 'object', properties: {n: {type: 'nope'}}},
        },
        async () => 'ok'
      );

    expect(register).toThrow(/broken_probe/);
  });
});
# Tool Input Validation

| Field  | Value                |
| ------ | -------------------- |
| Issue  | re-cinq/HALEngine#37 |
| Status | In Progress          |

Every tool registered in `src/orchestration/tools/registry.ts` declares a JSON Schema `inputSchema` that is forwarded to the configured AI provider, and `ToolRegistry.execute` validates the model-supplied `input` against that schema before calling the tool's executor. When validation fails, `execute` returns a rejection `ToolResponse` describing what was wrong rather than throwing, so the orchestrator feeds the failure back to the model as a `tool_result` within the existing tool-round budget.

## Validation at execute time

- When `input` omits a property listed in `required`, `ToolRegistry.execute` returns a `ToolResponse` whose `result` names the missing property as required and never invokes the executor ([validated by: rejects input missing a required property with a ToolResponse and never calls the executor](../../src/orchestration/tools/registry.acceptance.test.ts#L16), [validated by: returns a rejection naming location as required and never calls the executor for {}](../../src/orchestration/tools/registry.test.ts#L22)).
- When `input` supplies a property whose value does not match its declared JSON Schema type, `ToolRegistry.execute` returns a `ToolResponse` naming the failing field path and expected type without invoking the executor, and neither `result` nor the emitted log record contains the offending property value ([validated by: rejects a wrong-typed property naming the field and expected type without leaking the offending value to the result or logs](../../src/orchestration/tools/registry.acceptance.test.ts#L46), [validated by: rejects a number where a string is required naming the path and type but never the value](../../src/orchestration/tools/registry.test.ts#L33)).
- When `input` satisfies `required`, declared property types and `enum`, `ToolRegistry.execute` invokes the executor once and passes the input object through unchanged — including undeclared extra properties — without injecting `additionalProperties: false`, coercing types or applying defaults.
- When `ToolRegistry.execute` is called with a tool name that has not been registered, it throws `Unknown tool: <name>` because an unregistered tool is a programming or configuration error rather than a recoverable input mistake.

## Schema compilation and caching

- A static `ToolDefinition` has its `inputSchema` compiled once at `register` time, so a schema that is not valid JSON Schema throws synchronously from `register` with an error message naming the offending tool ([validated by: throws at register time naming the tool when a static inputSchema cannot be compiled](../../src/orchestration/tools/registry.acceptance.test.ts#L94), [validated by: throws naming the tool when a static inputSchema cannot be compiled](../../src/orchestration/tools/registry.test.ts#L56)).
- A static tool's `inputSchema` is compiled at `register` time and reused on every `execute` call without re-reading or re-compiling `definition.inputSchema`.
- A function-valued `ToolDefinitionSource` resolves its definition on each `execute` call and validates against the `inputSchema` returned for that call, caching compiled validators by schema object reference (`WeakMap`) so distinct returned schemas each enforce their own rules.

## Orchestrator tool-loop recovery

- Because a schema rejection returns a `ToolResponse` instead of throwing, `src/orchestration/chatOrchestrator.ts` sends the rejection `result` back to the provider as a `tool_result` message, allowing the model to issue a corrected tool call on the next round and complete the turn within `maxToolRounds` ([validated by: returns a schema rejection as a tool_result in the orchestrator loop so the model can correct the call on the next round](../../src/orchestration/tools/registry.acceptance.test.ts#L112)).
